import { Button, FormControl, MenuItem, Select, Slider } from "@mui/material";
import { useEffect, useState } from "react";
import jsondata from "../json/interrogartive.json";
import arrayShuffle from "array-shuffle";
import "../style/level1.css";
import { DragDropContext, Droppable, Draggable } from "react-beautiful-dnd";
import Swal from "sweetalert2";
import { useNavigate } from "react-router-dom";
import ReactGA from "react-ga4";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import { useTranslation } from "react-i18next";
import info from "../Images/hint2.png";

function Level1() {
  let [ArrIndex, setArrIndex] = useState(0);
  var [mainArr, setmainArr] = useState([]);
  let [currentsentence, setCurrentsentence] = useState();
  let [currentquestion, setCurrentQuestion] = useState();
  let [currentquestionarr, setCurrentquestionarr] = useState([]);
  var [shuffledcurrquearr, setShuffledcurrquearr] = useState([]);
  var [currentwordarr, setCurrentwordarr] = useState([]);
  var [currwordfeedback, setCurrwordfeeback] = useState();
  var [changecolor, setChangecolor] = useState(0);
  var [changecolor, setChangecolor] = useState([]);
  let [flag1, setFlag1] = useState(false);
  let [flag2, setFlag2] = useState(false);
  let [flag3, setFlag3] = useState(true);
  var [flag, setFlag] = useState(false);
  var [score, setScore] = useState(0);
  const navigate = useNavigate();
  const { t, i18n } = useTranslation();
  const [currsentfeedback, setCurrsentfeedback] = useState();
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("level 1 page");
  let [level, setLevel] = useState("Level 1");

  useEffect(() => {
    if (mainArr.length === 0)
      addToMainArr(arrayShuffle(Object.values(jsondata.level1)));
  }, []);

  const addToMainArr = (arrElement) => {
    setmainArr((prev) => [...prev, ...arrElement]);
  };

  useEffect(() => {
    console.log("mainArr ==> ", mainArr);
    if (mainArr.length !== 0) {
      const currentItem = mainArr[ArrIndex];
      if (currentItem) {
        currentsentence = currentItem.sentence;
        setCurrentsentence(currentsentence);
        currentquestion = currentItem.question;
        setCurrentQuestion(currentquestion);
        currentwordarr = currentItem.slot;
        setCurrentwordarr(currentwordarr);
      }
    }
  }, [mainArr, ArrIndex]);

  useEffect(() => {
    if (currentquestion) {
      const questionArray =
        typeof currentquestion === "string" ? currentquestion.split(" ") : [];
      setCurrentquestionarr(questionArray);
    }
  }, [currentquestion]);

  useEffect(() => {
    shuffledcurrquearr = arrayShuffle(currentquestionarr);
    setShuffledcurrquearr(shuffledcurrquearr);
  }, [currentquestionarr]);

  const onDragComplete = (result) => {
    // Handle drag completion logic here
    if (!result.destination) return;
    var arr = [...shuffledcurrquearr];
    //Changing the position of Array element
    let removedItem = arr.splice(result.source.index, 1)[0];
    arr.splice(result.destination.index, 0, removedItem);
    //Updating the list
    shuffledcurrquearr = arr;
    setShuffledcurrquearr(shuffledcurrquearr);
    const equalValues =
      shuffledcurrquearr.length === currentquestionarr.length &&
      shuffledcurrquearr.every(
        (value, index) => value === currentquestionarr[index]
      );
    if (equalValues) {
      console.log("matched");
    } else {
      console.log("not matched");
    }
    flag1 = true;
    setFlag1(flag1);
    var changecolorTemp = changecolor;
    for (let i = 0; i < currentquestionarr.length; i++) {
      if (shuffledcurrquearr[i] == currentquestionarr[i]) {
        console.log("TO change to green ======================>");
        document.getElementById(i).style.backgroundColor = "#098B0D";
        document.getElementById(i).style.color = "white";
        changecolorTemp[i] = 1;
      } else {
        console.log("TO change to red ======================>");
        document.getElementById(i).style.backgroundColor = "#BF4C4C";
        document.getElementById(i).style.color = "white";
        changecolorTemp[i] = 2;
      }
    }
    changecolor = changecolorTemp;
    setChangecolor(changecolor);
    if (changecolor.every((value, index) => value === 1)) {
      flag3 = false;
      setFlag3(flag3);
      setFlag(false);
      score = score + 1;
      setScore(score);
    }
    return false;
  };

  // const verify = (e, i, ele) => {
  //   if (flag1 == true) {
  //     if (changecolor[i] === 2) {
  //       for (var i = 0; i < currentwordarr.length; i++) {
  //         if (ele == currentwordarr[i].word) {
  //           console.log("words are ==>", currentwordarr[i].feedback);
  //           currwordfeedback = currentwordarr[i].feedback;
  //           setCurrwordfeeback(currwordfeedback);
  //           setFlag(true);
  //           setCurrsentfeedback(
  //             <div style={{ textAlign: "center" }}>
  //               Incorrect! <b style={{ color: "red" }}>{ele}</b>{" "}
  //               {currwordfeedback}
  //             </div>
  //           );
  //         }
  //       }
  //     }
  //   }
  // };

  const verify = (e, i, ele) => {
    if (flag1 == true) {
      currwordfeedback = currentwordarr[i].feedback;
      setCurrwordfeeback(currwordfeedback);
      if (changecolor[i] === 2) {
        for (var i = 0; i < currentwordarr.length; i++) {
          if (ele == currentwordarr[i].word) {
            currwordfeedback = currentwordarr[i].feedback;
            setCurrwordfeeback(currwordfeedback);
            setFlag(true);
            setCurrsentfeedback(
              <div style={{ textAlign: "center" }}>
                Incorrect! <b style={{ color: "red" }}>{ele}</b>{" "}
                {currwordfeedback}<br />
                Refer help
              </div>
            );
          }
        }
      } else {
        setCurrsentfeedback(
          <div style={{ textAlign: "center" }}>
            Correct! <b style={{ color: "green" }}>{ele}</b>{" "}
            is correctly placed
          </div>
        );
      }
    }
  };

  const handlenextbtn = () => {
    if (ArrIndex === mainArr.length-1) {
      // setTimeout(() => {
        flag2 = true;
        setFlag2(flag2);
      // }, 500);
      ReactGA.event({
        action:
          "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Clicked on Next button",
        category: "English CDAC-OlabsNxtG-En-24 | level-1 Next button clicked",
        label:
          "English CDAC-OlabsNxtG-En-24 | level-1 Next button clicked and all sentences are completed.",
      });
      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-1 "Next" button',
        "Clicked",
        'Level-1 "Next" button clicked and all sentences are completed.'
      );
    } else {
      ReactGA.event({
        action:
          "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Clicked on Next button",
        category: "English CDAC-OlabsNxtG-En-24 | level-1 Next button clicked",
        label:
          "English CDAC-OlabsNxtG-En-24 | level-1 Next button clicked for next sentence.",
      });
      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-1 "Next" button',
        "Clicked",
        'Level-1 "Next" button for next sentence.'
      );
      ArrIndex = ArrIndex + 1;
      setArrIndex(ArrIndex);
      flag3 = true;
      setFlag3(flag3);
      setFlag(false);
      for (let i = 0; i < currentquestionarr.length; i++) {
        document.getElementById(i).style.backgroundColor = "#f0c5c5";
      }
      currentsentence = [];
      setCurrentsentence(currentsentence);
      currentquestion = [];
      setCurrentQuestion(currentquestion);
      currentquestionarr = [];
      setCurrentquestionarr(currentquestionarr);
      shuffledcurrquearr = [];
      setShuffledcurrquearr(shuffledcurrquearr);
    }
  };

  const handleskipbtn = () => {
    if (ArrIndex === mainArr.length-1) {
      // setTimeout(() => {
        flag2 = true;
        setFlag2(flag2);
      // }, 500);
      ReactGA.event({
        action:
          "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Clicked on Skip button",
        category: "English CDAC-OlabsNxtG-En-24 | level-1 Skip button clicked",
        label:
          "English CDAC-OlabsNxtG-En-24 | level-1 Skip button clicked and all sentences are completed.",
      });
      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-1 "Skip" button',
        "Clicked",
        'Level-1 "Skip" button and all sentences are completed.'
      );
    } else {
      ReactGA.event({
        action:
          "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Clicked on Skip button",
        category: "English CDAC-OlabsNxtG-En-24 | level-1 Skip button clicked",
        label:
          "English CDAC-OlabsNxtG-En-24 | level-1 Skip button clicked for next sentence.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-1 "Skip" button',
        "Clicked",
        'Level-1 "Skip" button for next sentence.'
      );
      ArrIndex = ArrIndex + 1;
      setArrIndex(ArrIndex);
      flag3 = true;
      setFlag3(flag3);
      setFlag(false);
      for (let i = 0; i < currentquestionarr.length; i++) {
        document.getElementById(i).style.backgroundColor = "#f0c5c5";
      }
      currentsentence = [];
      setCurrentsentence(currentsentence);
      currentquestion = [];
      setCurrentQuestion(currentquestion);
      currentquestionarr = [];
      setCurrentquestionarr(currentquestionarr);
      shuffledcurrquearr = [];
      setShuffledcurrquearr(shuffledcurrquearr);
    }
  };

  const handlerestartbtn = () => {
    ReactGA.event({
      action:
        "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Clicked on Restart button",
      category: "English CDAC-OlabsNxtG-En-24 | level-1 Restart button clicked",
      label:
        "English CDAC-OlabsNxtG-En-24 | level-1 Restart button clicked for reattempt the level1.",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-1 "Restart" button',
      "Clicked",
      'Level-1 "Restart" button for reattempt the level1.'
    );

    window.location.reload();
  };

  const handleinfobtn = () => {
    Swal.fire({
      title: "Help",
      text: "The structure of an interrogative sentence is as follows: Auxiliary Verb + Subject + Main Verb + the rest of the sentence.",
    });
    ReactGA.event({
      action:
        "English Punctuation mark | CDAC-OlabsNxtG-En-35 | Clicked on Help icon.",
      category: "English CDAC-OlabsNxtG-En-35 | level-1 help icon clicked.",
      label:
        "English CDAC-OlabsNxtG-En-35 | level-1 help icon clicked for additional punctuation mark information.",
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-1 Help icon',
      "Clicked",
      'Level-1 help icon clicked for additional punctuation mark information.'
    );
  };

  const handleLevelChange = (event) => {
    switch (event.target.value) {
      case "Level 1":
        navigate("/launchpage/englishactivity/level1");
        break;
      case "Level 2":
        ReactGA.event({
          action:
            "English Interrogative sentences | CDAC-OlabsNxtG-En-24 | Clicked on Levels dropdown button",
          category:
            "English CDAC-OlabsNxtG-En-24 | level-1 Levels dropdown button clicked",
          label:
            "English CDAC-OlabsNxtG-En-24 | level-1 Levels dropdown button clicked to navigate to level 2.",
        });

        SendLogData(
          sendJsonMessage,
          pageName,
          'Level-1 "Levels" button',
          "Clicked",
          'Level-1 "Levels" dropdown button to navigate to level 2.'
        );
        navigate("/launchpage/englishactivity/level2");
        break;
      default:
        console.log("Bad choice!");
        break;
    }
  };

  return (
    <div
      className="row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        {flag2 ? (
          <div
            className=""
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF 0% 0% no-repeat padding-box",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
            }}
          >
            <div className="d-flex justify-content-between align-items-center mb-3">
              <div className="flex-grow-1 text-center" style={{ fontSize: "calc(1rem + .4vw)" }}>
                <b>{t("level_1_title")}</b>
              </div>
              <FormControl size="small" sx={{ minWidth: 120 }}>
                <Select
                  labelId="demo-simple-select-label"
                  id="demo-simple-select"
                  value={level}
                  onChange={handleLevelChange}
                  sx={{
                    bgcolor: "green",
                    borderRadius: 1,
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green",
                    },
                    color: "white",
                  }}
                >
                  <MenuItem value="Level 1">{t("level_1")}</MenuItem>
                  <MenuItem value="Level 2">{t("level_2")}</MenuItem>
                </Select>
              </FormControl>
            </div>

            <div
              className="d-flex justify-content-center align-items-center"
              style={{ minHeight: "50vh" }}
            >
              <div
                className="col-sm-4 text-center"
                style={{
                  boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px",
                  padding: "7vh 4vh 7vh 4vh",
                  backgroundColor: "#EDF6FA",
                  fontSize: "calc(.6rem + .4vw)"
                }}
              >
                <p style={{ fontWeight: "bolder" }}>
                  You have scored {score} out of {mainArr.length} sentences.
                </p>
                <div>
                  <Button variant="contained" onClick={handlerestartbtn} style={{backgroundColor: "#0F477E", fontSize: "calc(.6rem + .4vw)"}}>
                    {t("restart")}
                  </Button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div
            className=""
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF 0% 0% no-repeat padding-box",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
            }}
          >
            <div className="d-flex justify-content-between align-items-center mb-3">
              <div className="flex-grow-1 text-center" style={{ fontSize: "calc(1rem + .4vw)" }}>
                <b>{t("level_1_title")}</b>
              </div>
              <FormControl size="small" sx={{ minWidth: 120 }}>
                <Select
                  labelId="demo-simple-select-label"
                  id="demo-simple-select"
                  value={level}
                  onChange={handleLevelChange}
                  sx={{
                    bgcolor: "green",
                    borderRadius: 1,
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green",
                    },
                    color: "white",
                  }}
                >
                  <MenuItem value="Level 1">{t("level_1")}</MenuItem>
                  <MenuItem value="Level 2">{t("level_2")}</MenuItem>
                </Select>
              </FormControl>
            </div>

            <div
              className="d-flex align-items-center"
              style={{ marginTop: "27px", fontSize: "calc(.6rem + .4vw)" }}
            >
              <span className="me-3">Sentence</span>
              <Slider
                defaultValue={1}
                step={1}
                min={1}
                max={mainArr.length}
                value={ArrIndex+1}
                // onChange={(e, newValue) => setArrIndex(newValue)}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />
              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "60px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  fontSize: "calc(.6rem + .4vw)"
                }}
              >
                {ArrIndex+1}/{mainArr.length}
              </span>
            </div>

            <div
              style={{
                display: "flex",
                justifyContent: "end",
                marginTop: "1vh",
              }}
            >
              <img src={info} title="Help" onClick={handleinfobtn}></img>
            </div>

            <div className="">
              <div
                className="sentence"
                style={{
                  background: "#EDF6FA",
                  borderRadius: "40px",
                  boxShadow: "0px 3px 6px #00000029",
                  color: "#000000",
                  opacity: "1",
                  padding: "2%",
                  marginTop: "5px",
                  fontWeight: "bolder",
                  cursor: "pointer",
                }}
              >
                {currentsentence}
              </div>
            </div>

            <div className="d-flex justify-content-center align-items-center mt-5">
              <div className="">
                <DragDropContext onDragEnd={onDragComplete}>
                  <Droppable droppableId="characters" direction="horizontal">
                    {(provided) => (
                      <div
                        className="characters d-flex flex-wrap"
                        {...provided.droppableProps}
                        ref={provided.innerRef}
                      >
                        {shuffledcurrquearr.map((item, index) => (
                          <Draggable
                            key={index}
                            draggableId={"" + index}
                            index={index}
                          >
                            {(provided) => (
                              <div
                                className={"item-card"}
                                ref={provided.innerRef}
                                {...provided.draggableProps}
                                {...provided.dragHandleProps}
                                onClick={(event) => verify(event, index, item)}
                                id={index}
                              >
                                <div className="letter" style={{ fontSize: "calc(.6rem + .4vw)" }}>{item}</div>
                              </div>
                            )}
                          </Draggable>
                        ))}
                        {provided.placeholder}
                      </div>
                    )}
                  </Droppable>
                </DragDropContext>
              </div>
            </div>

            <div className="mt-5 d-flex justify-content-around">
              <Button
                variant="contained"
                onClick={handleskipbtn}
                sx={{ backgroundColor: "#0F477E", fontSize: "calc(.6rem + .4vw)" }}
                disabled={!flag3}
              >
                {t("skip")}
              </Button>
              <Button
                variant="contained"
                onClick={handlenextbtn}
                sx={{ backgroundColor: "#0F477E", fontSize: "calc(.6rem + .4vw)" }}
                disabled={flag3}
              >
                {t("next")}
              </Button>
            </div>

            <div className="d-flex justify-content-center align-items-center">
              <div
                className={`mt-5 text-center p-3 ${flag3 ? "d-none" : "d-block"
                  }`}
                style={{
                  width: "auto",
                  height: "auto",
                  background: "#ffffff",
                  boxShadow: "0px 0px 10px rgba(0, 0, 0, 0.5)",
                  borderRadius: "50px",
                  padding: "2%",
                  fontWeight: "bolder",
                  fontSize: "calc(.6rem + .4vw)"
                }}
              >
                "
                <span style={{ fontWeight: "bold", color: "green" }}>
                  {currentquestion}
                </span>
                " is a complete interrogative sentence.
              </div>
            </div>

            <div
              className="row justify-content-center"
              style={{ marginTop: "2vh" }}
            >
              {flag ? (
                <div
                  className="d-flex justify-content-center align-items-center"
                  style={{
                    width: "auto",
                    height: "auto",
                    background: "rgb(255, 255, 255)",
                    boxShadow: "rgba(0, 0, 0, 0.5) 0px 0px 10px",
                    borderRadius: "50px",
                    padding: "1rem",
                    fontSize: "calc(.6rem + .4vw)"
                  }}
                >
                  {currsentfeedback}
                </div>
              ) : (
                ""
              )}
            </div>
          </div>
        )}
      </div>

      <div className="col-sm-3 d-flex align-items-center">
        <div
          className=""
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center subheading"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            {t("instruction")}
          </div>
          <div style={{ maxHeight: "50vh", padding: "2%", fontSize: "calc(.6rem + .4vw)" }}>
            <div>

              {flag3 == false ? (
                <ul className="">
                  <li>{t("instruction_1_8")}</li>
                </ul>
              ) : flag2 == true ? (
                <ul className="">
                  <li>{t("instruction_1_9")}</li>
                </ul>
              ) : (
                <ul className="">
                  <li>{t("instruction_1_1")}</li>
                  <li>{t("instruction_1_2")}</li>
                  <li>{t("instruction_1_3")}</li>
                  <li>{t("instruction_1_4")}</li>
                  <li>{t("instruction_1_5")}</li>
                  <li>{t("instruction_1_6")}</li>
                  <li><u>{t("note")}</u>: {t("instruction_1_7")}</li>
                </ul>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Level1;
